<script setup lang="ts">
import { ref,computed } from 'vue'
import { ElMessageBox } from 'element-plus'
import { api } from '../../api'
import { usePage,perform,busy,user } from '../../state'
import type { Row } from '../../domain'
import PageHeader from '../../components/PageHeader.vue'
import DataTable from '../../components/DataTable.vue'
import LoadState from '../../components/LoadState.vue'
import OperatorDialogs from '../../components/OperatorDialogs.vue'
const users=ref<Row[]>([]),accounts=ref<Row[]>([]),changes=ref<Row[]>([]),tab=ref('users')
const createOpen=ref(false),resetOpen=ref(false),target=ref<Row>({})
const tabs=computed(()=>user.value?.role==='ADMIN'?[['users','客户档案'],['accounts','交易账户与卡'],['changes','换卡核准']]:[['users','客户档案'],['accounts','交易账户与卡']])
const {loading,error,load}=usePage(async()=>{[users.value,accounts.value,changes.value]=await Promise.all([api.get('/admin/users'),api.get('/admin/accounts'),user.value?.role==='ADMIN'?api.get('/admin/card-change-requests'):Promise.resolve([])])})
async function toggle(row:Row){await perform(()=>api.patch('/admin/users/'+row.id,{enabled:!(row.enabled===true||row.enabled===1)}),load)}
async function receive(row:Row){let reason:string;try{const value=await ElMessageBox.prompt('记录模拟收款能力变更原因。停用扣款与阻止收款是不同状态。','收款路径处置',{inputValidator:value=>!!value?.trim()||'请填写处置原因',confirmButtonText:'保存',cancelButtonText:'取消'});reason=value.value}catch{return};await perform(()=>api.patch('/admin/bank-cards/'+(row.bankCardId||row.cardId||row.id)+'/receive-state',{state:row.receiveState==='BLOCKED'?'RECEIVABLE':'BLOCKED',reason}),load)}
async function approve(row:Row){let reason:string;try{const value=await ElMessageBox.prompt('请确认同银行同持卡人模拟核验，填写核准理由；受阻待支付款按授权链改付。','核准换卡',{inputValidator:value=>!!value?.trim()||'请填写核准理由',confirmButtonText:'核准并生效',cancelButtonText:'取消'});reason=value.value}catch{return};await perform(()=>api.post('/admin/card-change-requests/'+row.id+'/approve',{reason}),load)}
</script>
<template><PageHeader title="客户与账户" subtitle="管理客户资格、独立资金账户和受控结算路径。"><button v-if="user?.role==='ADMIN'" class="button primary" @click="createOpen=true">＋ 创建操作员</button><button class="button" @click="load">刷新</button></PageHeader><LoadState :loading="loading" :error="error" @retry="load"/><div class="tabs"><button v-for="t in tabs" :key="t[0]" :class="{active:tab===t[0]}" @click="tab=t[0]">{{ t[1] }}</button></div><section v-if="tab==='users'" class="panel"><DataTable :rows="users" :columns="[{key:'id',label:'客户ID'}, {key:'username',label:'用户名'}, {key:'displayName',label:'模拟持卡人'}, {key:'role',label:'角色'}, {key:'riskLevel',label:'风险等级'}, {key:'riskExpiresAt',label:'测评有效期'}, {key:'opened',label:'已开户',kind:'bool'}, {key:'enabled',label:'可登录',kind:'bool'}]"><template #actions="{row}"><button v-if="row.role!=='ADMIN' && user?.role==='ADMIN'" class="text-button" :disabled="busy>0" @click="toggle(row)">{{ row.enabled?'停用':'启用' }}</button><button v-if="user?.role==='ADMIN'" class="text-button" :disabled="busy>0" @click="target=row;resetOpen=true">重置密码</button></template></DataTable></section><section v-else-if="tab==='accounts'" class="panel"><p class="notice">停用扣款不会阻断存量退款与赎回。收款受阻必须保留应付款并等待处置，不能标为已到账。</p><DataTable :rows="accounts" :columns="[{key:'userId',label:'客户'}, {key:'accountNo',label:'交易账户'}, {key:'bankName',label:'银行'}, {key:'simNumber',label:'模拟卡'}, {key:'bindingVersion',label:'版本'}, {key:'status',label:'扣款状态',kind:'state'}, {key:'receiveState',label:'收款状态',kind:'state'}, {key:'available',label:'可用（元）',kind:'money'}, {key:'frozen',label:'冻结（元）',kind:'money'}]"><template #actions="{row}"><button v-if="user?.role==='ADMIN'" class="text-button" :disabled="busy>0" @click="receive(row)">{{ row.receiveState==='BLOCKED'?'恢复收款':'设置收款受阻' }}</button></template></DataTable></section><section v-else class="panel"><DataTable :rows="changes" :columns="[{key:'id',label:'申请'}, {key:'userId',label:'客户'}, {key:'tradingAccountId',label:'交易账户'}, {key:'bankName',label:'银行'}, {key:'holderName',label:'模拟持卡人'}, {key:'reason',label:'申请理由'}, {key:'status',label:'状态',kind:'state'}, {key:'approvalReason',label:'核准理由'}, {key:'createdAt',label:'申请时间',kind:'date'}]"><template #actions="{row}"><button v-if="row.status==='PENDING'||row.status==='SUBMITTED'" class="text-button" :disabled="busy>0" @click="approve(row)">核准换卡</button></template></DataTable></section><OperatorDialogs v-model:create-open="createOpen" v-model:reset-open="resetOpen" :target="target" @saved="load"/></template>
